SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Ampere's law"@en "Avogadro constant"@en "Biot-Savart law"@en "Boltzmann constant"@en "Carnot cycle"@en "Coulomb's law"@en "Faraday's law"@en "Gauss's law"@en "Kirchhoff's laws"@en "Lenz's law"@en "Lorentz force"@en "Maxwell's equations"@en "Ohm's law"@en "Poynting vector"@en "Snell's law"@en "aberration"@en "admittance"@en "ampere's law"@en "avogadro constant"@en "biot-savart law"@en "boltzmann constant"@en "canonical ensemble"@en "capacitance"@en "capacitor"@en "carnot cycle"@en "circular polarization"@en "coherence"@en "coherent light"@en "conductivity"@en "coulomb's law"@en "critical angle"@en "critical temperature"@en "current density"@en "dielectric"@en "displacement current"@en "electric charge"@en "electric current"@en "electric field"@en "electric potential"@en "electric potential energy"@en "electromagnetic induction"@en "electromagnetic spectrum"@en "electromagnetic wave"@en "equation of state"@en "faraday's law"@en "focal length"@en "focal point"@en "gauge invariance"@en "gauge transformation"@en "gauss's law"@en "geometrical optics"@en "grand canonical ensemble"@en "heat engine"@en "ideal gas"@en "impedance"@en "inductance"@en "inductor"@en "irreversible process"@en "kirchhoff's laws"@en "lens"@en "lenz's law"@en "linear polarization"@en "lorentz force"@en "macrostate"@en "magnetic dipole"@en "magnetic field"@en "magnetic flux"@en "magnetic moment"@en "maxwell's equations"@en "microcanonical ensemble"@en "microstate"@en "ohm's law"@en "optical axis"@en "order parameter"@en "partition function"@en "permeability"@en "permittivity"@en "phase transition"@en "physical optics"@en "polarization"@en "polarized light"@en "poynting vector"@en "reactance"@en "reflection"@en "refraction"@en "refractive index"@en "resistance"@en "resistivity"@en "scalar potential"@en "snell's law"@en "statistical mechanics"@en "thermal efficiency"@en "total internal reflection"@en "vector potential"@en "voltage"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
